import struct, subprocess, random, os, sys, time

EX = "/workspace/artifacts/target/exiv2"
WORK = "/tmp/rtfuzz/work"
os.makedirs(WORK, exist_ok=True)
random.seed(1234)

def le16(v): return struct.pack('<H', v & 0xffff)
def le32(v): return struct.pack('<I', v & 0xffffffff)
def be16(v): return struct.pack('>H', v & 0xffff)
def be32(v): return struct.pack('>I', v & 0xffffffff)

INTERESTING = [0,1,2,3,4,7,8,15,16,26,31,32,64,100,127,128,255,256,511,512,1024,4096,65535,65536,0x7fffffff,0x80000000,0xfffffffe,0xffffffff,0xfffffff0,0x10000]

def rint():
