def tiff_entry(tag, ty, count, val):
    return struct.pack('<HHI', tag & 0xffff, ty & 0xffff, count & 0xffffffff) + (val if isinstance(val, bytes) else le32(val))

def tiff_file(entries, junk_tail=64):
    return b'II*\x00\x08\x00\x00\x00' + le16(len(entries)) + b''.join(entries) + le32(0) + bytes(random.getrandbits(8) for _ in range(junk_tail))

