PLAIN_TAGS = [0x0100,0x0101,0x0102,0x0103,0x0106,0x010f,0x0110,0x0111,0x0112,0x0115,0x0116,0x0117,0x011a,0x011b,0x011c,0x0128,0x0131,0x0132,0x013b,0x013e,0x013f,0x0201,0x0202,0x8298,0x829a,0x829d,0x9000,0x9003,0x9004,0x9101,0x9102,0x9201,0x9202,0x9204,0x9207,0x9209,0x9286,0x9c9b,0x9c9c,0x9c9d,0x9c9e,0x9c9f,0xa000,0xa001,0xa002,0xa003,0xa20e,0xa20f,0xa210,0xa214,0xa215,0xa217,0xa300,0xa301,0xa401,0xa402,0xa403,0xa405,0xa406,0xa407,0xa408,0xa409,0xa40a,0xa40b,0xa40c,0xa420,0xea1c,0xfde8,0x00fe,0x00ff,0x0002,0x0007,0x000d,0x0010,0x0018,0x001c,0x0023,0x0024,0x0028,0x0090,0x0091,0x0094,0x0095,0x00a0,0x00a7,0x00b0,0x00bb,0x0e00]

def gen_tiff():
    n = random.randint(1, 12)
    entries = []
    for _ in range(n):
        tag = random.choice(POINTER_TAGS + PLAIN_TAGS)
        ty = random.choice([1,2,3,4,5,7,9,10,13,16,17,18])
        count = random.choice([1,1,1,2,4, rint()])
