def jpeg_wrap(app1payloads):
    out = b'\xff\xd8'
    for p in app1payloads:
        p = p[:65000]
        out += b'\xff\xe1' + struct.pack('>H', len(p)+2) + p
    out += b'\xff\xe0\x00\x10JFIF\x00\x01\x01\x00\x00\x01\x00\x01\x00\x00'
    out += b'\xff\xd9'
    return out

def box(t, payload):
    return struct.pack('>I4s', 8+len(payload), t) + payload
