        body = bytes([(os_<<4)|ls_, (bs_<<4)|(is_ if random.random()<0.5 else 0)])
        body += struct.pack('>H', n_items)
        for i in range(n_items):
            body += struct.pack('>H', i+1)  # id
            if random.random() < 0.5:
                body += struct.pack('>H', random.choice([0,1,0xffff]))  # construction_method (v1/v2)
            body += struct.pack('>H', random.choice([0, 0xffff]))  # data ref
            body += (0).to_bytes(bs_, 'big')
            ec = random.randint(1, 3)
            body += struct.pack('>H', ec)
            for _ in range(ec):
                if is_:
                    body += (0).to_bytes(is_, 'big')
                body += rint().to_bytes(os_ or 1, 'big', signed=False) if os_ else b''
                body += (rint() & ((1<<(8*(ls_ or 1)))-1)).to_bytes(ls_ or 1, 'big') if ls_ else b''
        children += fullbox(b'iloc', random.choice([0,1,2]), 0, body)
    if random.random() < 0.4:
        ipco_items = b''
        for _ in range(random.randint(1,3)):
            kind = random.choice([b'ispe', b'pixi', b'colr', b'irot', b'clap', b'av1C'])
            if kind == b'ispe':
                ipco_items += fullbox(b'ispe', 0, 0, be32(rint()) + be32(rint()))
            elif kind == b'pixi':
                ipco_items += fullbox(b'pixi', 0, 0, bytes([random.randint(0,255) for _ in range(random.randint(0,8))]))
            else:
                ipco_items += box(kind, bytes(random.getrandbits(8) for _ in range(random.randint(0, 16))))
        children += box(b'iprp', box(b'ipco', ipco_items))
