        ipma_body = le32(1) + le16(1) + bytes([random.randint(0,8)])
        children += fullbox(b'ipma', random.choice([0,1]), random.choice([0,1]), ipma_body)
    if random.random() < 0.3:
        # Exif box inline
        t = gen_tiff()
        children += box(b'Exif', le32(random.choice([0, rint() & 0xff])) + t[:random.randint(0, len(t))])
    if random.random() < 0.3:
        children += box(b'mime', b'\x00' * random.randint(0, 20))
    if random.random() < 0.3:
        children += fullbox(b'iref', random.choice([0,1]), 0, box(b'cdsc', be16(1) + be16(1) + be16(random.randint(0, 0xffff))))
    meta = fullbox(b'meta', 0, 0, hdlr + children)
    extra = b''
    if random.random() < 0.5:
        extra += box(b'mdat', bytes(random.getrandbits(8) for _ in range(random.randint(0, 64))))
    if random.random() < 0.3:
        extra += box(b'uuid', bytes(random.getrandbits(8) for _ in range(16)) + gen_tiff()[:random.randint(0, 200)])
    return ftyp + meta + extra

def gen_case():
    kind = random.random()
    if kind < 0.45:
        return 'avif', gen_bmff()
    elif kind < 0.8:
        return 'avif', bmff_wrap_exif()
    else:
        t = gen_tiff()
        return 'jpg', jpeg_wrap([b'Exif\x00\x00' + t])

def bmff_wrap_exif():
    # brand + meta with Exif item located via iloc into mdat with tiff
    brand = random.choice([b'avif', b'heic'])
    ftyp = box(b'ftyp', brand + le32(0) + brand + b'mif1')
    hdlr = fullbox(b'hdlr', 0, 0, b'\x00'*4 + b'pict' + b'\x00'*12 + b'P\x00')
    pitm = fullbox(b'pitm', 0, 0, le16(1))
    infe = fullbox(b'infe', 2, 0, struct.pack('>HH',1,0) + b'Exif' + b'E\x00')
    iinf = fullbox(b'iinf', 0, 0, struct.pack('>H',1) + infe)
    t = gen_tiff()
    mdat = box(b'mdat', t)
    def mk_iloc(off, ln):
        body = bytes([0x44, 0x00]) + struct.pack('>H',1) + struct.pack('>H',1) + struct.pack('>H',0) + le32(0) + struct.pack('>H',1) + be32(off & 0xffffffff) + be32(ln & 0xffffffff)
        return fullbox(b'iloc', 0, 0, body)
    iloc0 = mk_iloc(0, len(t))
    meta0 = fullbox(b'meta', 0, 0, hdlr + pitm + iinf + iloc0)
    off = len(ftyp) + len(meta0) + 8
    off = random.choice([off, off+random.randint(-8,8), rint()])
    ln = random.choice([len(t), rint()])
    iloc = mk_iloc(off, ln)
    meta = fullbox(b'meta', 0, 0, hdlr + pitm + iinf + iloc)
    return ftyp + meta + mdat

def run_one(idx):
    ext, data = gen_case()
    p = f'{WORK}/c{idx}.{ext}'
    with open(p, 'wb') as f:
        f.write(data)
    try:
        r = subprocess.run([EX, 'pr', p], capture_output=True, timeout=8)
        return (p, r.returncode, r.stdout[-300:], r.stderr[-300:])
    except subprocess.TimeoutExpired:
        return (p, 'TIMEOUT', b'', b'')

def main():
    start = time.time()
