            print("HIT", p, rc, (se or so)[:150].decode('latin1', 'replace'), flush=True)
        if n % 500 == 0:
            print(f"...{n} cases, {hits} hits, {time.time()-start:.0f}s", flush=True)
    print(f"TOTAL {n} cases {hits} hits")

main()
